sys_script_include.script:
// Role: answers "which CIs make up this service?" by following the CMDB relationships downwards
//       (Business Service -> Application Service -> servers, databases, DNS...).
//       The relationships live in the table cmdb_rel_ci. This class only reads them.
var CPMScope = Class.create();
CPMScope.prototype = {
  MAX_DEPTH: 3,     // how many levels of relationships are followed
  MAX_ITEMS: 100,   // safety limit for very large services

  initialize: function() {},

  // Role: the components of a CI as { componentId: depth }. depth 1 = directly related, 2 = related to those, and so on.
  componentsOf: function(rootId) {
    var found = {};
    var seen = {};
    var level = [rootId];
    var count = 0;
    seen[rootId] = true;

    for (var depth = 1; depth <= this.MAX_DEPTH && level.length; depth++) {
      var next = [];
      var rel = new GlideRecord('cmdb_rel_ci');
      rel.addQuery('parent', 'IN', level.join(','));
      rel.query();
      while (rel.next()) {
        var child = rel.getValue('child');
        if (seen[child]) continue;
        seen[child] = true;
        found[child] = depth;
        next.push(child);
        if (++count >= this.MAX_ITEMS) return found;
      }
      level = next;
    }
    return found;
  },

  // Role: one sentence listing the components of a CI today. It is frozen into the evidence when it is approved,
  //       so the audit trail still shows what the service was made of on that day, even if the CMDB changes later.
  snapshot: function(rootId) {
    var ids = Object.keys(this.componentsOf(rootId));
    if (!ids.length) return 'No component was related to this CI in the CMDB at the time of approval.';

    var parts = [];
    var ci = new GlideRecord('cmdb_ci');
    ci.addQuery('sys_id', 'IN', ids.join(','));
    ci.orderBy('name');
    ci.query();
    while (ci.next()) parts.push(ci.getValue('name') + ' (' + ci.getDisplayValue('sys_class_name') + ')');

    var text = 'Components at approval (' + parts.length + '): ' + parts.join(', ');
    return text.length > 3900 ? text.substring(0, 3897) + '...' : text;
  },

  type: 'CPMScope'
};
